#include <stddef.h>
#include <stdlib.h>

template <int inst>
class __malloc_alloc_template {
public:
    static void deallocate(void *p, size_t) { free(p); }
};

template <bool threads, int inst>
class __my_default_alloc_template {
private:
    enum { _ALIGN = 8 };
    enum { _MAX_BYTES = 128 };
    enum { _NFREELISTS = _MAX_BYTES / _ALIGN };

    union _Obj {
        union _Obj *_M_free_list_link;
        char _M_client_data[1];
    };

    static _Obj *volatile _S_free_list[_NFREELISTS];

    static size_t _S_freelist_index(size_t bytes) {
        return ((bytes + _ALIGN - 1) / _ALIGN - 1);
    }

public:
    static void deallocate(void *p, size_t n) {
        _Obj *q = (_Obj *)p;
        _Obj *volatile *my_free_list;

        if (n > (size_t)_MAX_BYTES) {
            __malloc_alloc_template<0>::deallocate(p, n);
            return;
        }
        my_free_list = _S_free_list + _S_freelist_index(n);
        q->_M_free_list_link = *my_free_list;
        *my_free_list = q;
    }
};

typedef __my_default_alloc_template<false, 0> my_alloc;

template <class T>
class my_allocator {
public:
    typedef size_t size_type;
    typedef ptrdiff_t difference_type;
    typedef T *pointer;
    typedef const T *const_pointer;
    typedef T &reference;
    typedef const T &const_reference;
    typedef T value_type;

    template <class U>
    struct rebind {
        typedef my_allocator<U> other;
    };

    my_allocator() {}
    my_allocator(const my_allocator &) {}
    template <class U>
    my_allocator(const my_allocator<U> &) {}
    ~my_allocator() {}

    pointer address(reference x) const { return &x; }
    const_pointer address(const_reference x) const { return &x; }
    pointer allocate(size_type, const void * = 0);
    void deallocate(pointer p, size_type n) {
        my_alloc::deallocate(p, n * sizeof(T));
    }
    size_type max_size() const { return size_t(-1) / sizeof(T); }
    void construct(pointer p, const T &value) { new (p) T(value); }
    void destroy(pointer p) { p->~T(); }
};

template <class T, class U>
inline bool operator==(const my_allocator<T> &, const my_allocator<U> &) {
    return true;
}

template <class T, class U>
inline bool operator!=(const my_allocator<T> &, const my_allocator<U> &) {
    return false;
}

