template <class K>
class binary_tree_node {
public:
    binary_tree_node() {}
    void *_Left;
    void *_Right;
    K _Val;
};

template <class K>
class binary_tree {
public:
    typedef binary_tree_node<K> Node;
    typedef Node *Nodeptr;
    typedef K *Tptr;

protected:
    vector_allocator<Node> allocator;
    Nodeptr Head;
    size_t Size;

    static Nodeptr &Left(Nodeptr p) { return (Nodeptr &)p->_Left; }
    static Nodeptr &Right(Nodeptr p) { return (Nodeptr &)p->_Right; }
    static K &Value(Nodeptr p) { return p->_Val; }

    void Erase(Nodeptr x) {
        for (Nodeptr y = x; y; x = y) {
            Erase(Right(y));
            y = Left(y);
            Value(x).~K();
            allocator.deallocate(x, 1);
        }
    }

public:
    ~binary_tree() {
        Erase(Head);
        Head = 0;
        Size = 0;
        allocator.clear();
    }
};

